-- Differentiated Grade 7/8 ESL support sets. Original assignment results remain unchanged.
-- Six lesson-check items + four fresh-recheck items per lesson and group.
-- MCQ evidence only; no calibrated CEFR claim. Lessons 9/10 require prerequisite checks.
insert into public.academic_skill_evidence_focuses(registry_version_id,atomic_subskill_node_id,code,name,description,applicable_phases,source_method,source_fingerprint,status)
select n.registry_version_id,n.id,v.code,v.name,v.description,n.applicable_phases,'human_governed',md5(v.code),'active'
from (values ('eng.reading.explicit-information.locate-detail','eng.reading.explicit-information.locate-detail.focus.esl-short-text-detail','Locate details in a short text','Locate a specific stated detail in a self-contained short everyday text.'),('eng.reading.inference.attitude-feeling','eng.reading.inference.attitude-feeling.focus.esl-feeling-from-clues','Infer feelings from behaviour','Infer a person''s likely attitude or feeling using behavioural clues in a self-contained short text.'),('eng.reading.inference.attitude-feeling','eng.reading.inference.attitude-feeling.focus.esl-feeling-evidence','Select evidence for an inferred feeling','Select a textual clue that supports the stated inference about a person''s feeling.'),('eng.use-of-english.noun-phrase.articles-determiners','eng.use-of-english.noun-phrase.articles-determiners.focus.esl-article-reference','Use articles for sound and reference','Choose an article using the initial sound or whether a singular noun is already identified.'),('eng.use-of-english.noun-phrase.articles-determiners','eng.use-of-english.noun-phrase.articles-determiners.focus.esl-uncountable-reference','Use articles with uncountable nouns','Distinguish general uncountable reference with no article from a specifically identified uncountable noun with the.'),('eng.use-of-english.connectives.contrast-concession','eng.use-of-english.connectives.contrast-concession.focus.esl-everyday-contrast','Use connectors for contrast','Choose a connector that expresses contrast in an everyday sentence or short sequence.'),('eng.use-of-english.connectives.cause-effect','eng.use-of-english.connectives.cause-effect.focus.esl-everyday-cause','Use connectors for cause','Choose a connector that expresses cause in an everyday sentence or short sequence.'),('eng.use-of-english.connectives.cause-effect','eng.use-of-english.connectives.cause-effect.focus.esl-everyday-result','Use connectors for result','Choose a connector that expresses result in an everyday sentence or short sequence.'),('eng.use-of-english.voice-causative.passive','eng.use-of-english.voice-causative.passive.focus.esl-past-passive-be','Use was in a past passive','Choose the past form of be in a passive sentence about a finished time.'),('eng.use-of-english.reported-speech.reference','eng.use-of-english.reported-speech.reference.focus.esl-later-time-reference','Adjust reported time expressions','Change a time expression when reporting words from a different later time perspective.'),('eng.use-of-english.connectives.addition-sequence','eng.use-of-english.connectives.addition-sequence.focus.esl-everyday-sequence','Use connectors for sequence','Choose a connector that expresses sequence in an everyday sentence or short sequence.')) v(sub,code,name,description)
join public.academic_skill_registry_nodes n on n.code=v.sub and n.status='active'
on conflict(code) do nothing;
